import{_ as e,c as o,o as t,V as r}from"./chunks/framework.B6I5AJO8.js";const _=JSON.parse('{"title":"nb01 · Corpus discovery","description":"","frontmatter":{},"headers":[],"relativePath":"research/corpus-discovery.md","filePath":"research/corpus-discovery.md"}'),a={name:"research/corpus-discovery.md"},s=r('<h1 id="nb01-·-corpus-discovery" tabindex="-1">nb01 · Corpus discovery <a class="header-anchor" href="#nb01-·-corpus-discovery" aria-label="Permalink to &quot;nb01 · Corpus discovery&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb01_corpus_discovery.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>Of all the files across the Kalisio repositories, <strong>which ones should actually be indexed?</strong> Indexing everything wastes embedding budget and pollutes retrieval with noise (lockfiles, build artifacts, generated code, binaries).</p><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Profile-driven corpus discovery: a walker scans a repo tree and a <strong>filtering profile</strong> decides what is kept (by extension, path, size, …), so the same engine can target different corpora by swapping the profile rather than rewriting the walk.</p><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>A reusable discovery + filtering step that selects the files the rest of the pipeline chunks and embeds. This logic feeds the file-selection stage of the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>.</p>',8),i=[s];function n(c,h,d,l,p,u){return t(),o("div",null,i)}const b=e(a,[["render",n]]);export{_ as __pageData,b as default};
